#include <stdint.h>

// AI: below section was generated by an AI
// Phase integration for dynamic effect controls. Rates and waveform scaling come
// from this release's FX.cpp and util.cpp. Unlike absolute time * rate, integration
// changes only future motion when a sensor updates the rate.
// This is plain value state: Segment's copies (including effect crossfades) own
// independent clocks without allocations, shared pointers or per-frame heap work.
struct EffectClocks {
  static constexpr unsigned CHANNELS = 8;
  uint64_t phase[CHANNELS] = {}; // Q32.32: whole ticks/cycles and fractional progress
  uint32_t last[CHANNELS] = {};
  uint8_t initialized = 0;

  void reset() { initialized = 0; }

  // now is the clock domain used for elapsed time (milliseconds or frame count).
  // seed selects the initial phase, usually absolute time for existing sync or 0
  // for a new timer. Each channel must keep one clock domain and one unit of phase.
  uint64_t advance(uint32_t now, uint32_t numerator, uint32_t denominator, unsigned channel, uint32_t seed) {
    if (channel >= CHANNELS || denominator == 0) return 0;
    const uint8_t mask = uint8_t(1U << channel);
    if (!(initialized & mask)) {
      const uint64_t product = uint64_t(seed) * numerator;
      phase[channel] = ((product / denominator) << 32) + (((product % denominator) << 32) / denominator);
      initialized |= mask;
    } else {
      const uint32_t elapsed = now - last[channel]; // unsigned subtraction survives clock rollover
      if (!elapsed) return phase[channel]; // repeated samples in a pixel loop need no division
      const uint64_t product = uint64_t(elapsed) * numerator;
      // Divide the full elapsed interval, not a pre-rounded rate. Rounding the
      // fractional increment upward costs less than one Q32 bit per sample and
      // prevents an exact 3-frame interval from accidentally taking 4 frames.
      const uint64_t increment = ((product / denominator) << 32)
                               + (((product % denominator) << 32) + denominator - 1) / denominator;
      phase[channel] += increment; // unsigned phase rollover is intentional
    }
    last[channel] = now;
    return phase[channel];
  }

  // One event per call, preserving fractional progress when the period changes.
  // Reset at the event, like the original lastEvent = now timers (no catch-up burst).
  bool due(uint32_t now, uint32_t period, unsigned channel = 0, bool enabled = true) {
    const uint64_t value = advance(now, enabled ? 1 : 0, period ? period : 1, channel, 0);
    if (channel >= CHANNELS || value < (uint64_t(1) << 32)) return false;
    phase[channel] = 0;
    return true;
  }
};

// Keep a particle's reference velocity across slider edits, including zero.
// Rebase only when the physics engine changes its velocity (e.g. a collision),
// so repeated one-point speed edits cannot accumulate integer rounding errors.
struct EffectVelocity {
  int8_t referenceX, referenceY;
  uint8_t referenceSpeed;
  int8_t appliedX, appliedY;

  void reset(int8_t x, int8_t y, uint8_t speed) {
    referenceX = appliedX = x;
    referenceY = appliedY = y;
    referenceSpeed = speed ? speed : 1;
  }

  static int8_t scaled(int8_t velocity, uint8_t speed, uint8_t reference) {
    const int32_t product = int32_t(velocity) * speed;
    int32_t result = (product + (product < 0 ? -int32_t(reference / 2) : int32_t(reference / 2))) / reference;
    if (result > 127) result = 127;
    if (result < -127) result = -127;
    return int8_t(result);
  }

  void apply(int8_t &x, int8_t &y, uint8_t speed, uint8_t previousSpeed) {
    if (previousSpeed && (x != appliedX || y != appliedY)) reset(x, y, previousSpeed);
    x = appliedX = scaled(referenceX, speed, referenceSpeed);
    y = appliedY = scaled(referenceY, speed, referenceSpeed);
  }
};
// AI: end
